import SwiftUI
import UIKit
import BitmovinPlayer

@main
struct MinimalPlayerApp: App {
    var body: some Scene {
        WindowGroup {
            if let url = URL(string: "https://example.com/video/master.m3u8") {
                MinimalPlayerView(licenseKey: "YOUR_PLAYER_KEY", sourceURL: url)
            } else {
                Text("Invalid source URL")
            }
        }
    }
}

struct MinimalPlayerView: UIViewRepresentable {
    let licenseKey: String
    let sourceURL: URL

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeUIView(context: Context) -> PlayerView {
        let config = PlayerConfig()
        config.key = licenseKey
        config.playbackConfig.isAutoplayEnabled = true
        config.playbackConfig.isMuted = true
        #if os(tvOS)
        config.styleConfig.userInterfaceType = .system
        #endif
        let player = PlayerFactory.createPlayer(playerConfig: config)
        context.coordinator.player = player
        player.add(listener: context.coordinator)
        let view = PlayerView(player: player, frame: .zero)
        let source = SourceFactory.createSource(from: SourceConfig(url: sourceURL, type: .hls))
        player.load(source: source)
        return view
    }

    func updateUIView(_ view: PlayerView, context: Context) {}

    static func dismantleUIView(_ view: PlayerView, coordinator: Coordinator) {
        guard let player = coordinator.player else { return }
        coordinator.player = nil
        player.remove(listener: coordinator)
        view.player = nil
        player.destroy()
    }

    final class Coordinator: NSObject, PlayerListener {
        var player: Player?

        func onPlayerError(_ event: PlayerErrorEvent, player: Player) {
            guard player === self.player else { return }
            print("Player error \(event.code)")
        }

        func onSourceError(_ event: SourceErrorEvent, player: Player) {
            guard player === self.player else { return }
            print("Source error \(event.code)")
        }
    }
}

@StateObject private var model = PlayerModel(
    licenseKey: bitmovinLicenseKey(),
    analyticsLicenseKey: bitmovinAnalyticsLicenseKey()
)

func makeSourceConfig(callbackJournal: NativeCallbackJournal? = nil) -> SourceConfig {
    let config = SourceConfig(url: url, type: type.sdkType)
    config.title = title.isEmpty ? nil : title
    config.posterSource = posterURL
    if let startOffset { config.options.startOffset = startOffset }
    config.options.startOffsetTimelineReference = timelineReference.sdkValue
    advanced.apply(to: config, callbackJournal: callbackJournal)
    return config
}

func effect(for configuration: ValidatedConfiguration) -> ConfigurationEffect {
    if configuration.player != playerSettings { return .recreatePlayer }
    if configuration.source != sourceSettings { return .reloadSource }
    return .none
}

if let factory = uiMode.factoryFunction,
   let js = Bundle.main.url(forResource: "bitmovinplayer-ui", withExtension: "js"),
   let css = Bundle.main.url(forResource: "bitmovinplayer-ui", withExtension: "css") {
    config.styleConfig.playerUiJs = js
    config.styleConfig.playerUiCss = css
    let uiConfig = BitmovinUserInterfaceConfig()
    uiConfig.uiManagerFactoryFunction = factory
    config.styleConfig.userInterfaceConfig = uiConfig
}

if let value = values["StyleConfig.playerUiJs"], !value.isEmpty { config.styleConfig.playerUiJs = URL(string: value)! }
if let value = values["StyleConfig.playerUiCss"], !value.isEmpty { config.styleConfig.playerUiCss = URL(string: value)! }
if let value = values["StyleConfig.supplementalPlayerUiCss"] { config.styleConfig.supplementalPlayerUiCss = value.isEmpty ? nil : URL(string: value) }

func makeUIView(context: Context) -> UIView {
    let container = UIView()
    let view = PlayerView(player: model.player, frame: .zero, playerViewConfig: model.makePlayerViewConfig())
    context.coordinator.container = container
    context.coordinator.playerView = view
    context.coordinator.embed(view, in: container)
    view.fullscreenHandler = context.coordinator
    model.attachApiView(view)
    return container
}

private var configuredView: VideoPlayerView {
    let view = VideoPlayerView(player: model.player, playerViewConfig: model.makePlayerViewConfig())
        .isPictureInPictureEnabled($model.boundPiPEnabled)
        .isPictureInPictureAvailable($model.boundPiPAvailable)
        .isPictureInPictureActive($model.boundPiPActive)
        .scalingMode($model.boundScalingMode)
    #if os(tvOS)
    return view
    #else
    return view.showSkipControlsInPictureInPicture($model.boundPiPSkipControls)
    #endif
}

func coordinate(player: Player, join: Bool) throws {
    let session = try selectedSession()
    guard !player.isDestroyed else { throw failure("Create a player before coordinating it.") }
    player.sharePlay.coordinate(with: session)
    if join { session.join() }
    status = join ? "The current SDK player was coordinated with the selected OS session; join was requested." : "The current SDK player was coordinated with the selected OS session."
    refresh()
}

private func bindApiPlayerEvents() {
    guard apiEventsEnabled else { return }
    let player = self.player
    let listener = PlayerApiEventListener { [weak self, weak player] api, timestamp in
        guard let self, let player, self.player === player else { return }
        self.recordApiEvent(api, timestamp: timestamp, owner: "Player")
    }
    playerApiListener = listener
    if apiEventTransport == .listener { player.add(listener: listener) }
    else { playerApiPublishers = NativePublisherSubscriptions.player(player, receiver: listener) }
}

private func retireApiPlayerEvents() {
    playerApiPublishers.removeAll()
    if let listener = playerApiListener { player.remove(listener: listener) }
    playerApiListener = nil
}

guard !analyticsLicenseKey.isEmpty else {
    return PlayerFactory.createPlayer(playerConfig: config)
}
return PlayerFactory.createPlayer(
    playerConfig: config,
    analytics: .enabled(analyticsConfig: AnalyticsConfig(licenseKey: analyticsLicenseKey))
)
